/**
 * Conversations (register G189): the lore animals, trees, rocks, peat bogs,
 * barnacles, patches, shrines and placed Icons (G202) tell, one step at a
 * time, in the shared scripted dialogue. Data: js/conversations-data.js (generated by
 * tools/build-conversations.mjs); rules and the player's one record:
 * js/conversations.js. The Street Spirits keep their own feature and read
 * the same record (features/street-spirits-feature.js).
 *
 * Behaviour from GameServerJS (CC0):
 * - Offer on collision: each teller's onPlayerCollision walks its
 *   `conversations` list and offers the first that conversations_offer
 *   allows, then calls out (pc.conversations_offer_bubble), e.g.
 *   trant_base onPlayerCollision (trant_fruit.js 684-692), mineable_rock
 *   (rock_beryl_1.js 285-294, nothing while the rock is mined out:
 *   include/mining.js isUseable 135-137), patch.js 654-662, npc_shrine_base
 *   (npc_shrine_alph.js 563-592), npc_chicken.js 1299-1325 (nothing while
 *   incubating), npc_piggy.js 1059-1079 via npc_animal 2595-2602, and the
 *   Icons' icon_base (items/include/icon.js 565-575). The source's hit boxes
 *   are 400 x 400 (apiSetHitBox(400, 400) on all of them but the chicken,
 *   which sets none, the remake gives it a small one, and the Icons, 300 x
 *   250: icon_alph.js onCreate 315).
 * - Talk to: shown only while the class has an offered conversation
 *   (verbs.talk_to conditions, "I have something to tell you!"), hidden on
 *   a rooked teller; the shrines list what any class offered of their own
 *   conversations (conversations_offered_for_item). The handler runs the
 *   first. The Piggy's quests come first (npc_piggy.js 999-1018): with the
 *   Greedy Street Spirit to offer or hand in, Talk to stays the quest's.
 * - Steps: each conversation_run_<id> is the teller's line and one answer;
 *   the last answer completes it. The Surfeit of Cherries 3 hands over 250
 *   Cherries on its third answer (trant_fruit.js 869-882); every Icon
 *   conversation gives 111 iMG on its last answer (stats_add_xp(111, false),
 *   e.g. icon_pot.js 389-399), with the mood bonus as js/mood-xp.js pays it.
 * - Resume (conversations_set_current_state / conversations_login,
 *   inc_conversations.js 178-220): every line shown saves where the player
 *   is in the conversation; after a reload the conversation opens again at
 *   that line if its teller is on the player's street within 300 x 150 px
 *   (the saved state stays for the next load otherwise). Rewards already
 *   given are not given again (replay). Talk to after closing the dialogue
 *   starts from the first line again (msg.choice empty), as the source's did.
 * - Not built: the Heli Kitty (npc_kitty_chicken) offers the chicken's
 *   conversations but its talk_to is always hidden (npc_kitty_chicken.js
 *   531-534), so it would only use up offers.
 *
 * Talk to: animals and trees already have a "talk to" (content.js single
 * lines); with a conversation offered it runs the conversation instead
 * (runVerbOverride). Rocks ("inspect"), shrines, patches, peat, barnacles,
 * Batterflies and Icons get a "talk to" (verb id convo_talk) only while one
 * is offered (verbOverride).
 *
 * QA: &convo=dev (the source's dev-server rules: no login wait, no
 * donate_to_all_shrines wait, 10 s timeouts, 5 s on a chain);
 * &convoquest=done and &convolevel=<n> meet the canoffer quest and level
 * terms; &convolore=<id,id> records conversations as told;
 * &convodemo=<id> records everything before <id> as told (its chain in
 * progress when it is a later level), turns on dev rules and the quest and
 * level terms, and stands the player beside the nearest teller of <id> on
 * this street; &convoautoplay=1 then talks to it and answers every step
 * (=talk only opens the conversation, =<n> answers n steps and leaves it
 * open, for reload-resume QA; &convowait=<ms> waits after the offer);
 * &convonext=spirit then walks to the street's Street Spirit and talks to it
 * once it offers.
 * Canvas: convoOffered, convoActive, convoLast, convoHeld (why the last
 * teller walked into held its offer), convoCompleted,
 * convoCompletedCount, convoChains, convoDemo, convoTellers, convoState
 * (cls:id:step of the saved state), convoResume (resumed:<id>:<step>,
 * waiting, or kept when no teller was in range).
 */

import { addItem, ensureItem } from '../inventory.js?v=catalog-unified-4';
import { isPoisoned } from '../tree-poison.js';
import { GREEDY_ACTS, GREEDY_STREET_SPIRIT_QUEST_ID, canOfferGreedyFirst } from '../greedy-street-spirit.js?v=greedy-story-2';
import { questStatus } from '../quest-offers.js';
import { questDoneAt } from '../quests.js';
import { grantMoodXp } from '../mood-xp.js';
import { CONVERSATIONS, TELLERS } from '../conversations-data.js?v=g202-1';
import {
  CONVERSATION_RULES,
  clearCurrentState,
  completeConversation,
  conversationBeats,
  conversationRecord,
  currentState,
  hasCompleted,
  markHeard,
  offerBubble,
  offerFor,
  prerequisitesOf,
  restoreConversationRecord,
  resumeTarget,
  setCurrentState,
  talkableFor,
} from '../conversations.js?v=g202-1';

export const CONVERSATIONS_FEATURE_ID = 'conversations';
export const CONVO_TALK_VERB = 'convo_talk';
const TALK_TOOLTIP = 'I have something to tell you!';
const SCAN_MS = 150;

/** Collision boxes (w, h) around the teller's feet; the source's 400 x 400, the chicken's own, the Icons' 300 x 250. */
const ICON_BOX = Object.freeze([300, 250]);
const HIT_BOX = Object.freeze({ default: [400, 400], npc_chicken: [120, 120] });
/** How long after the first street of a load a cut-off conversation may resume (tellers register a moment late). */
const RESUME_WINDOW_MS = 15000;

let sessionStart = Date.now();
let streetEnteredAt = 0;
let nextScanAt = 0;
let near = new WeakMap();
/** { id, cls, target } while a conversation is open. */
let active = null;
let lastConvo = '';
let lastHeld = '';
let publishAt = 0;
let guard = false;
let demo = null;
/** conversations_login: one try per load, while the first street's tellers appear. */
let resume = { pending: true, until: 0, status: '' };
/** Effects of a reward on the last answer, shown with the completion line. */
let rewardEffects = null;

const record = () => conversationRecord();

function devRules(engine) {
  return engine.param('convo') === 'dev' || engine.param('spiritconvo') === 'dev' || Boolean(demo);
}

function qaQuest(engine) {
  return engine.param('convoquest') === 'done' || Boolean(demo);
}

function playerLevel(engine) {
  const qa = Number(engine.param('convolevel')) || (demo ? 99 : 0);
  return Math.max(Number(engine.pc?.level) || 0, qa);
}

function ctxFor(engine, now, target) {
  const questDone = (id) => qaQuest(engine) || questStatus(engine.questState || {}, id) === 'done';
  return {
    now,
    dev: devRules(engine),
    sessionStart,
    streetEnteredAt,
    shrinesDone: questDone(CONVERSATION_RULES.shrineQuest),
    // inc_conversations.js 99: ts_done (0 for a save finished before it was kept, or QA).
    shrinesDoneAt: qaQuest(engine) ? 0 : questDoneAt(engine.questState || {}, CONVERSATION_RULES.shrineQuest),
    questDone,
    level: playerLevel(engine),
    poisoned: Boolean(target && isPoisoned(target.state)),
    rooked: Boolean(target && takenOver(engine, target)),
  };
}

/** The teller class of a live target, or ''. Street spirits are their own feature's. */
export function tellerClass(target) {
  const cls = String(target?.classId || '');
  if (!TELLERS[cls] || !target.sprite || target.sprite.destroyed) return '';
  return cls;
}

/** Another feature has the target's menu (a rooked tree or animal, a shrine under attack). */
function takenOver(engine, target) {
  guard = true;
  try {
    return engine.query?.('verbOverride', target, engine) != null;
  } finally {
    guard = false;
  }
}

/** The source's teller-side holds: incubating chickens, mined-out rocks (offers), and the same for Talk to. */
function tellerHolds(target) {
  const s = target.state || {};
  if (target.classId === 'npc_chicken' && (s.incubatingEgg || s.flying)) return true;
  return false;
}

function rockSpent(target) {
  const rock = target.state?.rock;
  return Boolean(rock) && !(Number(rock.chunksRemaining) > 0);
}

/** The Piggy's quest comes first (npc_piggy.js 1003-1007). */
function piggyQuestFirst(engine, target) {
  if (target.classId !== 'npc_piggy') return false;
  const qs = engine.questState || {};
  if (canOfferGreedyFirst(qs, engine.pc || {}).ok) return true;
  const run = qs.active?.[GREEDY_STREET_SPIRIT_QUEST_ID];
  return Boolean(run) && GREEDY_ACTS.every((_a, i) => Number(run.progress?.[`read_act_${i + 1}`]) >= 1);
}

function talkable(engine, target, now = Date.now()) {
  const cls = tellerClass(target);
  if (!cls || tellerHolds(target)) return [];
  return talkableFor(record(), cls, now, devRules(engine));
}

function inBox(player, target) {
  const [w, h] = String(target.classId).startsWith('icon_') ? ICON_BOX : HIT_BOX[target.classId] || HIT_BOX.default;
  const spr = target.sprite;
  return Math.abs(player.x - spr.x) <= w / 2 && player.y <= spr.y + 40 && player.y >= spr.y - h;
}

function publish(engine) {
  const rec = record();
  const offered = Object.entries(rec.offered).flatMap(([cls, row]) => Object.keys(row).map((id) => `${cls}:${id}`));
  const completed = Object.values(rec.completed).flatMap((row) => Object.keys(row));
  engine.setData('convoOffered', offered.join(','));
  engine.setData('convoActive', active?.id || '');
  engine.setData('convoLast', lastConvo);
  engine.setData('convoHeld', lastHeld);
  engine.setData('convoCompleted', completed.filter((id) => CONVERSATIONS[id]).join(','));
  engine.setData('convoCompletedCount', String(completed.length));
  engine.setData('convoChains', Object.keys(rec.chainsInProgress).join(',') || 'none');
  engine.setData('convoDemo', demo ? `${demo.id}:${demo.status}` : '');
  const st = currentState(rec);
  engine.setData('convoState', st ? `${st.cls}:${st.id}:${st.step}` : '');
  engine.setData('convoResume', resume.status);
}

/** onPlayerCollision for every teller on the street: the first one walked into this scan offers. */
function scanOffers(engine, now) {
  const p = engine.player;
  if (!p || active) return;
  const busy = engine.busy?.() || engine.transientInstance?.();
  for (const target of engine.interactables || []) {
    const cls = tellerClass(target);
    if (!cls) continue;
    const inside = inBox(p, target);
    const was = near.get(target) || false;
    near.set(target, inside);
    // Collision fires on the way in; dev QA keeps checking while the player stands there.
    const entering = inside && (!was || (devRules(engine) && now >= (target._convoNextCheck || 0)));
    if (!entering || busy) continue;
    target._convoNextCheck = now + 1000;
    if (tellerHolds(target) || rockSpent(target)) continue;
    const res = offerFor(record(), cls, ctxFor(engine, now, target));
    if (!res.id) {
      lastHeld = `${cls}:${res.reason}`;
      continue;
    }
    lastConvo = `offered:${cls}:${res.id}`;
    engine.say(target, offerBubble(), CONVERSATION_RULES.bubbleMs);
    engine.save();
    return;
  }
}

function giveReward(engine, reward, last) {
  if (reward?.item) {
    ensureItem(reward.item);
    addItem(engine.inv, reward.item, reward.count);
    engine.refreshPack?.();
    engine.pushActivity(`You got ${reward.count} ${reward.item === 'cherry' ? 'Cherries' : reward.item}.`);
  }
  if (reward?.xp && engine.pc) {
    // stats_add_xp(n, false): the mood bonus applies (js/mood-xp.js).
    const landed = grantMoodXp(engine.pc, reward.xp);
    engine.updateHud?.();
    if (last) rewardEffects = { xp: landed };
    else engine.pushActivity({ base: 'You got iMG', effects: { xp: landed } });
  }
}

/** conversations_set_current_state: the teller and the line the player is on. */
function saveState(engine, cls, id, target, step) {
  const spr = target.sprite;
  setCurrentState(record(), { cls, id, step, street: engine.streetTsid || '', x: spr?.x || 0, y: spr?.y || 0, ref: target.iconId || '' });
}

/**
 * talk_to: run the first conversation this teller can tell, or (resume) the
 * saved one from its saved line; answers already given keep their rewards.
 */
function startConversation(engine, target, now = Date.now(), from = null) {
  const cls = tellerClass(target);
  const id = from ? from.id : talkable(engine, target, now)[0];
  if (!id || !engine.scriptedDialogue || !CONVERSATIONS[id]) return false;
  const def = CONVERSATIONS[id];
  const start = from ? Math.min(Math.max(0, from.step), def.steps.length - 1) : 0;
  active = { id, cls, target };
  lastConvo = `talking:${id}`;
  rewardEffects = null;
  // Only a state saved before this load resumes (a talk begun now is not reopened).
  resume.pending = false;
  markHeard(record(), id, now);
  saveState(engine, cls, id, target, start);
  const all = conversationBeats(id);
  const beats = all.slice(start).map((beat, k) => {
    const i = start + k;
    const reward = def.steps[i].reward;
    const last = i === all.length - 1;
    return {
      ...beat,
      onAnswer: () => {
        if (reward) giveReward(engine, reward, last);
        // The source saves the answer just given; the last one completes and clears it.
        if (!last) {
          saveState(engine, cls, id, target, i + 1);
          engine.save();
        }
      },
    };
  });
  engine.scriptedDialogue({
    title: def.title,
    kicker: target.label || 'Conversation',
    beats,
    cancelable: true,
    cancelLabel: 'Close',
    onComplete: () => {
      completeConversation(record(), cls, id, def.chain, Date.now());
      clearCurrentState(record());
      lastConvo = `completed:${id}`;
      endConversation(engine);
      const line = `You talked to the ${target.label || 'teller'}: ${def.title}`;
      if (rewardEffects) engine.pushActivity({ base: line, effects: rewardEffects });
      else engine.pushActivity(`${line}.`);
      rewardEffects = null;
      engine.save();
    },
  });
  engine.save();
  publish(engine);
  return true;
}

/**
 * conversations_login 192-220, once per load: the saved conversation opens
 * again at its line when its teller is on this street in range. A spirit's
 * state is the spirits feature's (it has its own teller).
 */
function resumeTick(engine, now) {
  if (!resume.pending || active || !engine.player || !streetEnteredAt) return;
  const st = currentState(record());
  if (!st || !TELLERS[st.cls]) {
    resume.pending = false;
    return;
  }
  if (!resume.until) resume.until = now + RESUME_WINDOW_MS;
  if (now > resume.until) {
    // 204-207: out of range or gone: the state waits for the next login.
    resume = { pending: false, until: 0, status: `kept:${st.id}:${st.step}` };
    return;
  }
  resume.status = 'waiting';
  if (engine.busy?.() || engine.transientInstance?.() || engine.questDialogueOpen?.()) return;
  const targets = (engine.interactables || []).filter((t) => tellerClass(t)).map((t) => ({ cls: t.classId, x: t.sprite.x, y: t.sprite.y, ref: t.iconId || '', t }));
  const hit = resumeTarget(record(), { street: engine.streetTsid, player: engine.player, targets });
  // 210-214: the teller must still tell it.
  if (!hit || !TELLERS[st.cls].list.includes(st.id)) return;
  resume = { pending: false, until: 0, status: `resumed:${st.id}:${st.step}` };
  startConversation(engine, hit.t, now, { id: st.id, step: st.step });
}

function endConversation(engine) {
  if (active && lastConvo === `talking:${active.id}`) lastConvo = `closed:${active.id}`;
  active = null;
  publish(engine);
}

// ---------------------------------------------------------------------------
// QA
// ---------------------------------------------------------------------------

const OLD = () => Date.now() - CONVERSATION_RULES.offerTimeoutMs - 60_000;

function seedTold(ids) {
  const rec = record();
  let at = OLD() - ids.length * 1000;
  for (const id of ids) {
    at += 1000;
    if (hasCompleted(rec, id)) continue;
    const def = CONVERSATIONS[id];
    // Spirit ids and anything unknown go under a QA class; their own feature reads any class.
    completeConversation(rec, def?.tellers[0] || 'qa_lore', id, def?.chain || null, at);
  }
}

function seedQa(engine) {
  const lore = String(engine.param('convolore') || '').split(',').map((s) => s.trim()).filter((s) => /^\w+$/.test(s));
  if (lore.length) seedTold(lore);
  const id = String(engine.param('convodemo') || '');
  if (!CONVERSATIONS[id]) return;
  demo = { id, status: 'seeded', placed: false, autoplay: engine.param('convoautoplay') || '' };
  seedTold(prerequisitesOf(id));
  const def = CONVERSATIONS[id];
  const rec = record();
  // A later chain level waits on its own chain being in progress (seedTold already moved it on).
  if (def.chain && def.chain.level > 1) rec.chainsInProgress = { [def.chain.id]: OLD() };
}

function demoTick(engine, now) {
  if (!demo || demo.status === 'done' || !engine.player) return;
  if (!demo.placed) {
    const def = CONVERSATIONS[demo.id];
    const tellers = (engine.interactables || []).filter((t) => def.tellers.includes(tellerClass(t)));
    engine.setData('convoTellers', tellers.map((t) => t.classId).join(','));
    if (!tellers.length) {
      // Shrines and feature tellers register a moment after the street does.
      demo.status = now - streetEnteredAt > 15000 ? 'no-teller' : 'seeded';
      return;
    }
    const p = engine.player;
    const t = tellers.sort((a, b) => Math.abs(a.sprite.x - p.x) - Math.abs(b.sprite.x - p.x))[0];
    p.x = t.sprite.x + 70;
    p.y = t.sprite.y - 4;
    p.vx = 0;
    p.vy = 0;
    demo.placed = true;
    demo.target = t;
    demo.status = 'placed';
    return;
  }
  if (demo.status === 'placed' && talkable(engine, demo.target, now).includes(demo.id)) {
    demo.status = 'offered';
    demo.talkAt = now + Math.max(0, Number(engine.param('convowait')) || 0);
  }
  if (demo.autoplay && demo.status === 'offered' && now >= demo.talkAt && !engine.busy?.()) {
    demo.status = 'talking';
    const verb = (engine.targetVerbs(demo.target) || []).find((v) => v.id === CONVO_TALK_VERB || v.id === 'talk_to');
    if (verb) engine.beginVerb(demo.target, verb);
    demo.answerAt = now + 800;
  }
  // =1 answers every step; =<n> answers n and leaves the dialogue open (resume QA).
  const answers = demo.autoplay === '1' ? Infinity : Number(demo.autoplay) > 1 ? Number(demo.autoplay) : 0;
  if (demo.status === 'talking' && answers && active && now >= (demo.answerAt || 0) && (demo.answered || 0) < answers) {
    demo.answerAt = now + 500;
    demo.answered = (demo.answered || 0) + 1;
    if (typeof document !== 'undefined') document.getElementById('quest-dialogue-next')?.click();
  }
  if (demo.status === 'talking' && hasCompleted(record(), demo.id)) {
    demo.status = engine.param('convonext') === 'spirit' ? 'next' : 'done';
    demo.nextAt = now + 1500;
  }
  if (demo.status === 'next' && now >= demo.nextAt) spiritNext(engine, now);
}

/**
 * QA &convonext=spirit: after the demo conversation, stand beside the
 * street's Street Spirit and, once it has offered (its own rules, read from
 * the shared record), talk to it, so a spirit talk unlocked by this
 * conversation is shown for real.
 */
function spiritNext(engine, now) {
  const spirit = (engine.interactables || []).find((t) => String(t.classId || '').startsWith('street_spirit_') && t.state?.vendorKey && t.sprite && !t.sprite.destroyed);
  if (!spirit) return;
  const p = engine.player;
  if (!demo.spiritPlaced) {
    p.x = spirit.sprite.x - 70;
    p.y = spirit.sprite.y - 4;
    p.vx = 0;
    p.vy = 0;
    demo.spiritPlaced = true;
    return;
  }
  const cls = spirit.state?.spiritClass || '';
  const offered = Object.keys(record().offered?.[cls] || {});
  if (!offered.length) return;
  if (!demo.spiritTalkAt) demo.spiritTalkAt = now + Math.max(0, Number(engine.param('convowait')) || 0);
  if (now < demo.spiritTalkAt || engine.busy?.()) return;
  const verb = (engine.targetVerbs(spirit) || []).find((v) => v.id === 'talk_to');
  if (verb) engine.beginVerb(spirit, verb);
  demo.status = 'done';
}

export const conversationsFeature = {
  id: CONVERSATIONS_FEATURE_ID,

  init(engine) {
    sessionStart = Date.now();
    resume = { pending: true, until: 0, status: '' };
    seedQa(engine);
    publish(engine);
  },

  onStreetEnter(street, engine) {
    if (active) endConversation(engine);
    streetEnteredAt = Date.now();
    near = new WeakMap();
    if (demo && !demo.placed) demo.status = 'seeded';
  },

  onStreetClear() {
    near = new WeakMap();
    if (demo && demo.status !== 'done') {
      demo.placed = false;
      demo.target = null;
    }
  },

  onTick(dtMs, now, engine) {
    const wall = Date.now();
    if (active && !engine.questDialogueOpen?.()) endConversation(engine);
    if (wall >= nextScanAt) {
      nextScanAt = wall + SCAN_MS;
      resumeTick(engine, wall);
      scanOffers(engine, wall);
      demoTick(engine, wall);
    }
    if (wall >= publishAt) {
      publishAt = wall + 500;
      publish(engine);
    }
  },

  /**
   * Tellers without a "talk to" of their own (rocks, shrines, patches, peat,
   * barnacles, Batterflies) get one while a conversation is offered.
   */
  verbOverride(target, engine) {
    if (guard || !tellerClass(target) || !talkable(engine, target).length) return null;
    guard = true;
    let base;
    try {
      base = engine.targetVerbs(target) || [];
    } finally {
      guard = false;
    }
    if (base.some((v) => v.id === 'talk_to' && v.label === 'talk to')) return null;
    const verb = { id: CONVO_TALK_VERB, label: 'talk to', sort: 45, tooltip: TALK_TOOLTIP, enabled: true, reason: '', energy: 0, durationMs: 0 };
    return [...base, verb].sort((a, b) => (a.sort ?? 50) - (b.sort ?? 50));
  },

  /** Talk to with a conversation offered runs it (true); otherwise the target's own Talk to (null). */
  runVerbOverride(target, verbId, engine) {
    if (verbId !== CONVO_TALK_VERB && verbId !== 'talk_to') return null;
    if (!tellerClass(target) || active) return null;
    if (verbId === 'talk_to' && piggyQuestFirst(engine, target)) return null;
    if (takenOver(engine, target)) return null;
    return startConversation(engine, target, Date.now()) ? true : null;
  },

  save() {
    return record();
  },

  restore(slice, engine) {
    restoreConversationRecord(slice);
    if (engine) seedQa(engine);
  },

  /** QA / tests. */
  _state() {
    return { record: record(), active: active?.id || '', last: lastConvo, demo: demo ? { id: demo.id, status: demo.status } : null };
  },
};
